-- Single-clock platform adapter; generated PS/DDR/MIO design remains board owned.
-- PS/block-design-facing adapter; board pin/DDR/MIO wrapper is generated by Vivado.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.eat_config_pkg.all;
use work.eat_types_pkg.all;

entity eat_platform_wrapper is
  generic (
    G_ALLOW_STUB_SIM : boolean := false;
    G_RESIDENT_BANKS : positive := 3;
    G_WORDS_PER_BANK : positive := 90112
  );
  port (
    clk_i : in std_logic;
    arst_n_i : in std_logic;
    s_axi_awaddr_i : in std_logic_vector(C_AXIL_ADDR_BITS-1 downto 0);
    s_axi_awvalid_i : in std_logic;
    s_axi_awready_o : out std_logic;
    s_axi_wdata_i : in std_logic_vector(C_AXIL_DATA_BITS-1 downto 0);
    s_axi_wstrb_i : in std_logic_vector(C_AXIL_DATA_BITS/8-1 downto 0);
    s_axi_wvalid_i : in std_logic;
    s_axi_wready_o : out std_logic;
    s_axi_bresp_o : out std_logic_vector(1 downto 0);
    s_axi_bvalid_o : out std_logic;
    s_axi_bready_i : in std_logic;
    s_axi_araddr_i : in std_logic_vector(C_AXIL_ADDR_BITS-1 downto 0);
    s_axi_arvalid_i : in std_logic;
    s_axi_arready_o : out std_logic;
    s_axi_rdata_o : out std_logic_vector(C_AXIL_DATA_BITS-1 downto 0);
    s_axi_rresp_o : out std_logic_vector(1 downto 0);
    s_axi_rvalid_o : out std_logic;
    s_axi_rready_i : in std_logic;
    s_axis_tdata_i : in std_logic_vector(C_AXIS_BITS-1 downto 0);
    s_axis_tkeep_i : in std_logic_vector(C_AXIS_BITS/8-1 downto 0);
    s_axis_tlast_i : in std_logic;
    s_axis_tvalid_i : in std_logic;
    s_axis_tready_o : out std_logic;
    m_axis_tdata_o : out std_logic_vector(C_AXIS_BITS-1 downto 0);
    m_axis_tkeep_o : out std_logic_vector(C_AXIS_BITS/8-1 downto 0);
    m_axis_tlast_o : out std_logic;
    m_axis_tvalid_o : out std_logic;
    m_axis_tready_i : in std_logic;
    interrupt_o : out std_logic
  );
end entity;

architecture rtl of eat_platform_wrapper is
  signal reset_core:std_logic;
begin
  reset_sync:entity work.eat_reset_sync(rtl) port map(clk_i=>clk_i,arst_n_i=>arst_n_i,rst_o=>reset_core);
  peripheral:entity work.eat_fpga_top(rtl) generic map(G_RESIDENT_BANKS=>G_RESIDENT_BANKS,G_WORDS_PER_BANK=>G_WORDS_PER_BANK)
    port map(clk_i=>clk_i,rst_i=>reset_core,s_axi_awaddr_i=>s_axi_awaddr_i,s_axi_awvalid_i=>s_axi_awvalid_i,s_axi_awready_o=>s_axi_awready_o,s_axi_wdata_i=>s_axi_wdata_i,s_axi_wstrb_i=>s_axi_wstrb_i,s_axi_wvalid_i=>s_axi_wvalid_i,s_axi_wready_o=>s_axi_wready_o,s_axi_bresp_o=>s_axi_bresp_o,s_axi_bvalid_o=>s_axi_bvalid_o,s_axi_bready_i=>s_axi_bready_i,s_axi_araddr_i=>s_axi_araddr_i,s_axi_arvalid_i=>s_axi_arvalid_i,s_axi_arready_o=>s_axi_arready_o,s_axi_rdata_o=>s_axi_rdata_o,s_axi_rresp_o=>s_axi_rresp_o,s_axi_rvalid_o=>s_axi_rvalid_o,s_axi_rready_i=>s_axi_rready_i,s_axis_tdata_i=>s_axis_tdata_i,s_axis_tkeep_i=>s_axis_tkeep_i,s_axis_tlast_i=>s_axis_tlast_i,s_axis_tvalid_i=>s_axis_tvalid_i,s_axis_tready_o=>s_axis_tready_o,m_axis_tdata_o=>m_axis_tdata_o,m_axis_tkeep_o=>m_axis_tkeep_o,m_axis_tlast_o=>m_axis_tlast_o,m_axis_tvalid_o=>m_axis_tvalid_o,m_axis_tready_i=>m_axis_tready_i,interrupt_o=>interrupt_o);
end architecture;
